def run():
    for a in ARTICLES:
        cat = ArticleCategory.objects.get(id=a["category_id"])
        article, created = Article.objects.update_or_create(
            slug=a["slug"],
            defaults={
                "title": a["title"],
                "description": a["description"],
                "content": a["content"],
                "category": cat,
                "tags": a["tags"],
                "author": AUTHOR,
                "is_published": True,
            },
        )
        article.related_products.set(Product.objects.filter(id__in=a["products"]))
        print(("✓ ساخته شد" if created else "✓ به‌روزرسانی"), article.id, article.slug)

    for slug, extra in CATEGORY_APPEND.items():
        c = Category.objects.get(slug=slug)
        base = (c.description or "").strip()
        first_new_para = extra.split("\n\n")[0][:60]
        if first_new_para in base:
            print("= قبلاً اضافه شده:", slug)
            continue
        c.description = (base + "\n\n" + extra).strip() if base else extra
        c.save(update_fields=["description"])
        print("✓ توضیحات دسته غنی شد:", slug)


run()
